package dev.hexora.config;
import dev.hexora.enums.RoleType; import dev.hexora.model.User; import dev.hexora.repository.RoleRepository; import dev.hexora.repository.UserRepository; import dev.hexora.model.Role; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.crypto.password.PasswordEncoder; import java.util.Set;
@Configuration public class DataInitializer {
 @Bean CommandLineRunner seed(RoleRepository roles,UserRepository users,PasswordEncoder encoder,@Value("${app.bootstrap.username:}")String username,@Value("${app.bootstrap.email:}")String email,@Value("${app.bootstrap.password:}")String password){return args->{for(RoleType t:RoleType.values())roles.findByName(t).orElseGet(()->{Role r=new Role();r.setName(t);return roles.save(r);});if(!username.isBlank()&&!email.isBlank()&&!password.isBlank()&&!users.existsByUsernameIgnoreCase(username)){User u=new User();u.setUsername(username);u.setEmail(email.toLowerCase());u.setPassword(encoder.encode(password));u.setRoles(Set.of(roles.findByName(RoleType.ADMIN).orElseThrow()));users.save(u);}};}
}
